#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

namespace Internal {
    int marks(int m1, int m2) {
        return m1 + m2;
    }
}

namespace External {
    int marks(int m1, int m2) {
        return m1 + m2;
    }
}

int main() {
    int i1, i2, e1, e2;
    cin >> i1 >> i2 >> e1 >> e2;

    int internal_total = Internal::marks(i1, i2);
    int external_total = External::marks(e1, e2);
    int grand_total = internal_total + external_total;

    cout << "Internal Total: " << internal_total << '\n';
    cout << "External Total: " << external_total << '\n';
    cout << "Grand Total: " << grand_total << '\n';
    return 0;
}
